        {
          "id": "def-finite-probability-vector",
          "kind": "definition",
          "title": "Finite probability vectors",
          "deps": [],
          "dependency_level": 0,
          "proof_obligations": [
            "Specify the finite nonempty alphabet, nonnegative coordinates, normalization, and zero coordinates."
          ],
          "statement": "Let $\\mathcal X$ be a finite nonempty set. A **probability vector** on\n$\\mathcal X$ is a family $P=(p_x)_{x\\in\\mathcal X}$ of real numbers such that\n$p_x\\ge 0$ for every $x$ and $\\sum_{x\\in\\mathcal X}p_x=1$. Its support is\n$\\operatorname{supp}P:=\\{x\\in\\mathcal X:p_x>0\\}$. Coordinates outside the\nsupport are retained as zeros; they are not deleted from the alphabet.\n\nFor another probability vector $Q=(q_x)_{x\\in\\mathcal X}$, the notation\n$P\\ll Q$ means $\\operatorname{supp}P\\subseteq\\operatorname{supp}Q$. All\nfinite sums over $\\mathcal X$ use the displayed alphabet and ordinary finite\nreal arithmetic, extended to $+\\infty$ only where a later definition says so.",
          "justified_by": [],
          "sources": {
            "references": [
              {
                "title": "Yury Polyanskiy and Yihong Wu, Information Theory: From Coding to Learning, Chapter 1, §1.2",
                "url": "https://people.lids.mit.edu/yp/homepage/data/itbook-2022.pdf"
              },
              {
                "title": "Tim van Erven and Peter Harremoës, Rényi Divergence and Kullback-Leibler Divergence, §I-A",
                "url": "https://arxiv.org/pdf/1206.2459"
              }
            ]
          },
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          }
        },
        {
          "id": "lem-convex-generator-boundary-limits-exist",
          "kind": "lemma",
          "title": "Boundary limits of a normalized finite convex generator exist",
          "deps": [
            "def-convex-and-strictly-convex-functions-on-euclidean-sets",
            "def-complete-ordered-field",
            "def-real-numbers",
            "thm-reals-ordered-field",
            "cor-cauchy-reals-lub-complete"
          ],
          "dependency_level": 0,
          "proof_obligations": [
            "Prove existence of the zero boundary value and recession limit as extended-real limits, excluding negative infinity."
          ],
          "statement": "Let $f:(0,\\infty)\\to\\mathbb R$ be convex and satisfy $f(1)=0$. Then $f$\nis continuous on $(0,\\infty)$, and both extended-real limits\n$$f(0):=\\lim_{t\\downarrow0}f(t),\\qquad f_\\infty:=\\lim_{t\\to\\infty}\\frac{f(t)}t$$\nexist in $\\mathbb R\\cup\\{+\\infty\\}$; neither limit is $-\\infty$.",
          "justified_by": [],
          "sources": {
            "references": [
              {
                "title": "Yury Polyanskiy and Yihong Wu, Information Theory: From Coding to Learning, Chapter 7, §7.1",
                "url": "https://people.lids.mit.edu/yp/homepage/data/itbook-2022.pdf"
              },
              {
                "title": "Igal Sason and Sergio Verdú, f-Divergence Inequalities, §II-B, equations (35)–(39)",
                "url": "https://arxiv.org/pdf/1508.00335"
              }
            ]
          },
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-generated"
          },
          "proof_strategy": "direct"
        },
        {
          "id": "lem-finite-kl-generator-is-admissible",
          "kind": "lemma",
          "title": "The finite KL generator has the required convex boundary extension",
          "statement": "For $f(t)=t\\log t$ on $t>0$, one has $f(1)=0$, $f$ is convex on\n$(0,\\infty)$, $\\lim_{t\\downarrow0}f(t)=0$, and\n$\\lim_{t\\to\\infty}f(t)/t=+\\infty$.",
          "deps": [
            "def-natural-logarithm",
            "thm-natural-logarithm-laws",
            "thm-logarithm-derivative-and-integral",
            "thm-algebra-of-derivatives",
            "def-derivative",
            "cor-second-derivative-characterises-convexity",
            "thm-logarithm-slower-than-every-positive-power",
            "def-convex-and-strictly-convex-functions-on-euclidean-sets"
          ],
          "justified_by": [],
          "dependency_level": 0,
          "proof_strategy": "direct",
          "proof_obligations": [
            "Use logarithm differentiability and the second-derivative convexity criterion on (0,∞).",
            "Verify the 0+ boundary limit with log t/t→0 and the recession limit from log monotonicity and surjectivity."
          ],
          "sources": {
            "references": [
              {
                "title": "Yury Polyanskiy and Yihong Wu, Information Theory: From Coding to Learning, Chapter 7, §7.1",
                "url": "https://people.lids.mit.edu/yp/homepage/data/itbook-2022.pdf"
              },
              {
                "title": "Igal Sason and Sergio Verdú, f-Divergence Inequalities, §II-B, equations (43)–(45)",
