        {
          "id": "lem-finite-renyi-generators-are-convex",
          "kind": "lemma",
          "title": "The finite Rényi generators are convex with stated boundary values",
          "statement": "For $\\alpha>1$, the generator $h_\\alpha(t)=t^\\alpha-1$ is convex on\n$(0,\\infty)$, satisfies $h_\\alpha(1)=0$, has\n$h_\\alpha(0+)=-1$, and has recession limit\n$\\lim_{t\\to\\infty}h_\\alpha(t)/t=+\\infty$. For $0<\\alpha<1$, the generator\n$g_\\alpha(t)=1-t^\\alpha$ is convex on $(0,\\infty)$, satisfies\n$g_\\alpha(1)=0$, has $g_\\alpha(0+)=1$, and has recession limit\n$\\lim_{t\\to\\infty}g_\\alpha(t)/t=0$.",
          "deps": [
            "def-real-power",
            "thm-real-power-continuity-and-derivatives",
            "thm-algebra-of-derivatives",
            "cor-second-derivative-characterises-convexity",
            "def-natural-logarithm",
            "thm-natural-logarithm-laws",
            "thm-exponential-limits-and-range",
            "cor-exponential-reciprocal-and-positivity",
            "def-convex-and-strictly-convex-functions-on-euclidean-sets"
          ],
          "justified_by": [],
          "dependency_level": 0,
          "proof_strategy": "direct",
          "proof_obligations": [
            "Derive convexity from the second derivatives for each order range.",
            "Prove endpoint and recession limits with the positive-power representation and log/exponential limits."
          ],
          "sources": {
            "references": [
              {
                "title": "Yury Polyanskiy and Yihong Wu, Information Theory: From Coding to Learning, Chapter 7, §§7.1 and 7.12",
                "url": "https://people.lids.mit.edu/yp/homepage/data/itbook-2022.pdf"
              },
              {
                "title": "Tim van Erven and Peter Harremoës, Rényi Divergence and Kullback-Leibler Divergence, §II-A",
                "url": "https://arxiv.org/pdf/1206.2459"
              }
            ]
