          "axiom_use": "No choice axiom is used; this definition quantifies over supplied kernels and selects no versions."
        },
        {
          "id": "def-discrete-memoryless-channel",
          "kind": "definition",
          "title": "Finite discrete memoryless channels",
          "deps": [
            "def-channel-sequence",
            "def-finite-stochastic-kernel"
