      "items": [
        {
          "id": "def-qc-tqc-periodic-square-cellulation",
          "kind": "definition",
          "title": "Periodic square cellulation of the torus",
          "deps": [],
          "justified_by": [],
          "dependency_level": 0,
          "statement": "Fix an integer $L\\ge3$ and write $\\mathbb Z_L=\\mathbb Z/L\\mathbb Z$. The periodic square cellulation has vertices $q_{i,j}$, horizontal edges $h_{i,j}$ from $q_{i,j}$ to $q_{i+1,j}$, vertical edges $v_{i,j}$ from $q_{i,j}$ to $q_{i,j+1}$, and faces $f_{i,j}$, for $i,j\\in\\mathbb Z_L$. Every index is read modulo $L$. The boundary of $f_{i,j}$ consists of $h_{i,j},v_{i+1,j},h_{i,j+1},v_{i,j}$. Equivalently, this is the quotient of the unit square tiling of $\\mathbb R^2$ by translations in $L\\mathbb Z^2$. The cellulation has $L^2$ vertices, $2L^2$ edges, and $L^2$ faces. The condition $L\\ge3$ ensures that the four edges in each star and face are distinct, and that every edge has two distinct endpoints and two distinct incident faces. The vertex-edge graph joins vertices joined by an edge. The face-adjacency graph joins faces sharing an edge; both graphs are connected.",
          "proof_obligations": [
            "Give explicit endpoint/face incidence modulo L and verify each edge has two endpoints and two adjacent faces."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; the construction uses fixed finite coordinate sets.",
          "proof_strategy": "direct"
        },
        {
          "id": "lem-qc-tqc-finite-square-cycle-is-boundary",
          "kind": "lemma",
          "title": "Finite square-lattice cycles are boundaries",
          "deps": [],
          "justified_by": [],
          "dependency_level": 0,
          "statement": "In the infinite square lattice, every finitely supported edge chain over $\\mathbb F_2$ whose incidence at each vertex is even is the boundary of a finitely supported collection of square faces. The same conclusion holds for the translated dual square lattice.",
          "proof_obligations": [
            "Define finite edge chains on Z² and prove the explicit face-filling formula; verify the same under the dual-grid identification."
          ],
          "sources": {
            "references": [
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              },
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; the proof is a finite-support calculation over the two-element field.",
          "proof_strategy": "direct"
        },
        {
          "id": "def-qc-tqc-toric-checks",
          "kind": "definition",
          "title": "Toric star and plaquette checks",
          "deps": [
            "def-qc-tqc-periodic-square-cellulation",
            "def-qc-pauli-matrices",
            "def-qc-register-and-computational-basis",
            "def-qc-tensor-map",
            "lem-qc-tensor-product-basis-and-dimension"
          ],
          "justified_by": [],
          "dependency_level": 1,
          "statement": "For the periodic cellulation in [[def-qc-tqc-periodic-square-cellulation]], put one qubit on each edge, ordered lexicographically by $(i,j)$ and then with horizontal before vertical edges. The physical Hilbert space is $\\mathcal H_L=(\\mathbb C^2)^{\\otimes E}$, where $E$ is the edge set. For an edge $e$, write $X_e$ and $Z_e$ for the corresponding one-qubit Pauli acting on that tensor factor and as the identity on every other factor. Define the star and plaquette checks by $$A_{i,j}=X_{h_{i-1,j}}X_{h_{i,j}}X_{v_{i,j-1}}X_{v_{i,j}},\\qquad B_{i,j}=Z_{h_{i,j}}Z_{v_{i+1,j}}Z_{h_{i,j+1}}Z_{v_{i,j}}.$$ All indices are in $\\mathbb Z_L$.",
          "proof_obligations": [
            "Use the finite tensor-product Pauli definitions and state the check supports explicitly."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; each check is an explicit finite tensor product.",
          "proof_strategy": "direct"
        },
        {
          "id": "lem-qc-tqc-contractible-disk-lifts-to-plane",
          "kind": "lemma",
          "title": "A contractible toric disk lifts to the square grid",
          "deps": [
            "def-qc-tqc-periodic-square-cellulation"
          ],
          "justified_by": [],
          "dependency_level": 1,
          "statement": "Write the torus as $T_L=\\mathbb R^2/(L\\mathbb Z^2)$ with its periodic\nsquare cellulation. Let $D\\subset T_L$ be a nonempty compact embedded\ntopological disk with connected complement. Then the quotient map\n$\\pi:\\mathbb R^2\\to T_L$ has a lift $\\widetilde D\\subset\\mathbb R^2$ on\nwhich it is one-to-one and maps $\\widetilde D$ homeomorphically onto $D$.\nConsequently every finite primal or dual edge chain supported in $D$ lifts\nto a finite chain in the infinite square tiling, and cycles lift to cycles.",
          "proof_obligations": [
            "Use the explicit quotient map R²→R²/(LZ²), prove path-independent lifting over a simply connected disk, and use compactness/local finiteness to obtain a finite lifted cell subcomplex."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; the lift is unique after a basepoint is fixed.",
          "proof_strategy": "direct"
        },
        {
          "id": "lem-qc-tqc-toric-incidence-ranks",
          "kind": "lemma",
          "title": "Toric incidence maps have exactly one relation each",
          "deps": [
            "def-qc-tqc-periodic-square-cellulation",
            "thm-rank-nullity"
          ],
          "justified_by": [],
          "dependency_level": 1,
          "statement": "For $L\\ge3$, the $L^2$ star-support vectors in $\\mathbb F_2^E$ have span dimension $L^2-1$, and their only relation is their total sum. The $L^2$ face-boundary vectors have the same span dimension and their only relation is their total sum. The dual-face incidence statement has the same rank.",
          "proof_obligations": [
            "Prove connected incidence rank V−1 by spanning-tree elimination and prove the sole relation is constant on each connected graph. Apply also to the dual graph."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; all support spaces are finite binary vector spaces.",
          "proof_strategy": "direct"
        },
        {
          "id": "def-qc-tqc-toric-excitations",
          "kind": "definition",
          "title": "Toric e and m syndromes",
          "deps": [
            "def-qc-tqc-toric-checks",
            "def-qc-stabilizer-syndrome-and-logical-operators"
          ],
          "justified_by": [],
          "dependency_level": 2,
          "statement": "For a nonzero vector $\\psi$ that is a simultaneous eigenvector of all toric checks, its **e syndrome** is the set of vertices $q$ for which $A_q\\psi=-\\psi$, and its **m syndrome** is the set of faces $f$ for which $B_f\\psi=-\\psi$. A violated star is called an e defect and a violated plaquette is called an m defect. These are finite stabilizer-syndrome labels; the names do not assume that a material contains localized physical quasiparticles. These eigenvalue labels agree with the commutation-sign syndrome of [[def-qc-stabilizer-syndrome-and-logical-operators]] when a Pauli error acts on a common $+1$ check eigenvector, as verified below. The checks are Hermitian involutions, as verified below; thus their eigenvalues on any nonzero simultaneous eigenvector are indeed signs.",
          "proof_obligations": [
            "Define simultaneous syndrome projectors and distinguish the finite stabilizer model from physical particle language."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "John Preskill, Quantum Computation, Chapter 9: Topological Quantum Computation",
                "url": "https://www.preskill.caltech.edu/ph219/topological.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "not-applicable"
          },
          "axiom_use": "None; this item defines finite check eigenvalue labels.",
          "proof_strategy": "direct"
        },
        {
          "id": "lem-qc-tqc-toric-check-commutation",
          "kind": "lemma",
          "title": "Toric checks commute and have two global relations",
          "deps": [
            "def-qc-tqc-periodic-square-cellulation",
            "def-qc-tqc-toric-checks",
            "def-qc-pauli-matrices",
            "thm-qc-pauli-commutator-is-symplectic-pairing"
          ],
          "justified_by": [],
          "dependency_level": 2,
          "statement": "All star and plaquette checks of [[def-qc-tqc-toric-checks]] commute. The product of all stars is the identity, and the product of all plaquettes is the identity.",
          "proof_obligations": [
            "Compute Pauli signs from XZ=−ZX and show every edge appears twice in each global product."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
