          "axiom_use": "None; the proof counts finite edge incidences modulo two.",
          "proof_strategy": "direct"
        },
        {
          "id": "lem-qc-tqc-toric-cycle-quotient",
          "kind": "lemma",
          "title": "Toric cycle classes are determined by two winding parities",
          "deps": [
            "def-qc-tqc-periodic-square-cellulation",
            "lem-qc-tqc-toric-incidence-ranks"
          ],
          "justified_by": [],
          "dependency_level": 2,
          "statement": "Let $Z_1$ be the space of primal edge chains with even incidence at every\nvertex, and let $B_1$ be the span of the face boundaries. Then $B_1\\subseteq\nZ_1$, the quotient $Z_1/B_1$ has dimension two, and the two winding\nparities give coordinates on that quotient. The same statement holds for\ndual edge chains, with dual face boundaries (the stars around primal vertices) in place of primal face boundaries.\nThe horizontal loop $\\gamma_h=\\sum_i h_{i,0}$ has winding pair $(1,0)$,\nand the vertical loop $\\gamma_v=\\sum_j v_{0,j}$ has pair $(0,1)$; their dual\ncounterparts give the corresponding basis of the dual quotient.",
          "proof_obligations": [
            "Give an explicit spanning tree and cycle basis; establish the boundary subspace rank and show the two winding loops complete the basis."
          ],
          "sources": {
            "references": [
              {
                "title": "Eric Dennis, Alexei Kitaev, Andrew Landahl, and John Preskill, Topological quantum memory",
                "url": "https://arxiv.org/pdf/quant-ph/0110143"
              },
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-generated"
          },
          "axiom_use": "None; all chains and bases are finite over F2.",
          "proof_strategy": "direct"
        },
        {
          "id": "def-qc-tqc-toric-hamiltonian",
          "kind": "definition",
          "title": "Finite toric-code Hamiltonian",
          "deps": [
            "def-qc-tqc-toric-checks",
            "lem-qc-tqc-toric-check-commutation",
            "def-qc-pauli-matrices"
          ],
          "justified_by": [],
          "dependency_level": 3,
          "statement": "For $L\\ge3$ and couplings $J_e,J_m>0$, the finite toric-code Hamiltonian on $\\mathcal H_L$ is $$H_L=-J_e\\sum_{i,j\\in\\mathbb Z_L}A_{i,j}-J_m\\sum_{i,j\\in\\mathbb Z_L}B_{i,j}.$$ The energy unit is fixed by $J_e,J_m$. This is a finite-volume operator defined from the stabilizer checks; its definition makes no claim about a material realization or a thermodynamic phase.",
          "proof_obligations": [
            "Check H is Hermitian and commuting from the Pauli relations; state energy units and finite volume."
          ],
          "sources": {
            "references": [
              {
                "title": "Alexei Kitaev, Fault-tolerant quantum computation by anyons",
                "url": "https://arxiv.org/pdf/quant-ph/9707021"
              },
              {
                "title": "John Preskill, Quantum Computation, Chapter 9: Topological Quantum Computation",
                "url": "https://www.preskill.caltech.edu/ph219/topological.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "ai-altered",
