          "proof_strategy": "direct"
        },
        {
          "id": "thm-finite-index-ii1-basic-construction-jones-tower",
          "kind": "theorem",
          "title": "Ordinary finite-index II1 inclusions give the full Jones tower and Temperley–Lieb relations",
          "dependency_level": 5,
          "deps": [
