            "proof": "not-applicable"
          },
          "sources": [
            {
              "title": "Douglas and Reutter, Fusion 2-Categories and a State-Sum Invariant for 4-Manifolds, Construction 2.1.19 (algebraic background)",
              "url": "https://arxiv.org/pdf/1812.11933"
