        },
        {
          "id": "lem-modc-bounded-rank-structure-varieties-have-finitely-many-orbits",
          "kind": "lemma",
          "title": "Bounded-rank module-structure varieties have finitely many open orbits",
          "dependency_level": 5,
          "deps": [
