          "sources": {
            "references": [
              {
                "title": "N. Jacobson, Lectures on Quadratic Jordan Algebras, Tata Institute of Fundamental Research, 1969",
                "url": "https://mathweb.tifr.res.in/Documents/Publications/Lectures/tifr45.pdf"
